// English dictionary for the game (language switch, src/game/lang.ts).
// Nouns only, in parity with the Russian dictionary: WordNet 3.1 noun lemmas
// (https://wordnetcode.princeton.edu/, dict/index.noun) kept if present in
// dolph/dictionary popular.txt (https://github.com/dolph/dictionary) -- the
// frequency filter that trims WordNet's ~44k noun lemmas to the ~12k common ones.
// Filtered to lowercase a-z, length 2 and up (the original capped words at 10
// letters; the trie has no such limit).
// Regenerate (bash; reading files instead of piping into node's stdin — on Windows
// the pipe mangles UTF-8; then re-add this header in front of the output):
//   curl -sL -o popular.txt https://raw.githubusercontent.com/dolph/dictionary/master/popular.txt
//   curl -sL -o wn31.tar.gz https://wordnetcode.princeton.edu/wn3.1.dict.tar.gz
//   tar -xzf wn31.tar.gz dict/index.noun
//   node -e "const fs=require('fs');const p=new Set(fs.readFileSync('popular.txt','utf8').split(/\r?\n/).filter(Boolean));const n=new Set();for(const l of fs.readFileSync('dict/index.noun','utf8').split(/\r?\n/)){const w=l.split(' ')[0];if(/^[a-z]{2,}$/.test(w))n.add(w)}fs.writeFileSync('dictionary-en.ts','export const dictionary: string[] = '+JSON.stringify([...n].filter(w=>p.has(w)).sort())+';\n')"
